/* 单字段游标绑定原字段值，调用方不得直接修改。 */
typedef struct xhttpviacursor {
	const void* Source;
	size_t Size;
	size_t Offset;
	uint8 Validated;
} xhttpviacursor;



/* 重复字段游标绑定原字段数组并记录当前字段和字段内位置。 */
typedef struct xhttpviafieldcursor {
	const void* Source;
	size_t Count;
	size_t Field;
	size_t Offset;
	uint8 Validated;
} xhttpviafieldcursor;

#endif



